// ================================================================
//  ⚙️  الإعدادات — ده المكان الوحيد اللي محتاج تعدّل فيه
// ================================================================
const CONFIG = {
  // ---- بياناتك ----
  myName: 'Zyad Mohamed Abdelfattah',
  myEmail: 'you@example.com',               // الإيميل اللي هيوصله الملخص اليومي
  myPhone: '+20 1xx xxx xxxx',

  // ---- Google Sheet ----
  // افتح الشيت في المتصفح وانسخ اللينك كله وحطه هنا
  sheetUrl: 'PASTE_YOUR_GOOGLE_SHEET_URL_HERE',
  sheetName: 'Jobs',

  // ---- مفاتيح الذكاء الاصطناعي (حط المفتاح اللي عندك بس) ----
  keys: {
    gemini: 'PASTE_GEMINI_KEY_HERE',   // مجاني من aistudio.google.com
    openai: '',                        // اختياري (ChatGPT) من platform.openai.com
    claude: '',                        // اختياري (Claude) من console.anthropic.com
  },
  // 🧠 الفريق: واحد بيقيّم كل الوظايف، وواحد بيكتب الجوابات للوظايف الكويسة بس
  // المقيّم: Gemini Flash-Lite (مجاني وسريع، بيشتغل على كل وظيفة)
  scorer: { provider: 'gemini', model: 'gemini-2.5-flash-lite' },
  // الكاتب: Gemini Flash مجاني. لو عايز Claude أو ChatGPT يكتبوا، حط مفتاحه فوق وغيّر السطر ده لـ:
  //   { provider: 'claude', model: 'claude-sonnet-5-5' }   أو   { provider: 'openai', model: 'gpt-5-mini' }
  // (لو مفتاح الكاتب فاضي، المقيّم هو اللي هيكتب)
  writer: { provider: 'gemini', model: 'gemini-2.5-flash' },

  // ---- قواعد الفلترة ----
  minScoreToKeep: 45,      // أقل من كده مش هتتحط في الشيت
  dailyMinJobs: 10,        // الملخص اليومي فيه 10 وظايف على الأقل (لو موجودين)
  maxAiJobsPerRun: 25,     // أقصى عدد وظايف تتبعت للذكاء الاصطناعي في المرة

  // ---- التقديم بالإيميل ----
  // 0 = مفيش تقديم إلا لما تكتب «نعم» في عمود approve في الشيت
  // مثلاً 80 = قدّم لوحدك على أي وظيفة سكورها 80 أو أكتر ومعاها إيميل تقديم
  autoApplyMinScore: 0,
  maxEmailsPerRun: 5,
  // IDs ملفات السي في على Google Drive (افتح الملف ← Share ← Copy link، والـ ID هو اللي بين /d/ و /view)
  cvDriveIds: {
    qa: 'PASTE_DRIVE_FILE_ID',
    data_entry: 'PASTE_DRIVE_FILE_ID',
    wordpress: 'PASTE_DRIVE_FILE_ID',
    ai_trainer: 'PASTE_DRIVE_FILE_ID',
  },

  // ---- البحث ----
  linkedinKeywords: ['Arabic', 'data entry', 'QA tester', 'software tester', 'WordPress',
                     'AI trainer', 'annotation', 'Arabic content', 'Power BI', 'Excel'],
  linkedinLocations: ['Egypt', 'Saudi Arabia', 'United Arab Emirates'],
  mostaqlKeywords: ['ووردبريس', 'إدخال بيانات', 'اختبار تطبيق', 'اكسل', 'تفريغ'],
  baytPages: [
    'https://www.bayt.com/en/egypt/jobs/remote-jobs/',
    'https://www.bayt.com/en/saudi-arabia/jobs/remote-jobs/',
    'https://www.bayt.com/en/uae/jobs/remote-jobs/',
  ],
  remoteApiSearches: ['arabic', 'data entry', 'qa', 'wordpress', 'annotation'],

  // وظايف لازم يكون فيها كلمة من دول (في العنوان أو الوصف)
  includeRegex: 'arab|عرب|data entry|إدخال|ادخال|بيانات|qa\\b|quality|tester|testing|اختبار|wordpress|ووردبريس|woocommerce|elementor|annotat|label|rater|evaluat|ai train|transcri|تفريغ|excel|اكسل|power ?bi|gis|seo|content review|moderat|localiz',
  // وظايف تتشال على طول لو فيها كلمة من دول في العنوان
  excludeRegex: 'senior|sr\\.|lead|manager|head of|director|principal|architect|staff engineer|german|french|spanish|turkish|russian|hebrew|italian|portuguese|japanese|korean|chinese|dutch|polish|nurse|doctor|driver|sales|telesales|cold call',

  // ---- ملفك (اللي الذكاء الاصطناعي بيقارن بيه) — حقايق بس، من غير مبالغة ----
  profile: `Zyad Mohamed Abdelfattah, based in Kafr El Dawar, Beheira, Egypt. Remote only.
Languages: Arabic native (Egyptian + Modern Standard Arabic). English intermediate (working proficiency in writing; not fluent in speaking).
Experience:
- QA Tester, Findo Group, Oct 2025 – present (remote, full-time): manual testing of web and mobile apps (Flutter, iOS/Android), regression testing, bug reports in Jira with steps/expected/actual/severity/screenshots, testing AI features and evaluating AI answers, reviewing Arabic localization and right-to-left layouts. Wrote 7 structured QA reports covering 5 products and 69 issues.
- Built "QA Pro": a desktop testing tool (Electron + Playwright) with 20 automated test suites.
- Data Entry Specialist, Findo Group, about 2 years before the QA role: accurate data entry in Arabic and English, cleaning duplicates, reports in Excel, Word, PowerPoint; SQL to look up and update records.
Skills: Excel, Power BI, PowerPoint, Word, SQL, Python basics (no OOP yet), WordPress (WooCommerce stores, Elementor, security, backups, domains, hosting, SSL, SEO, publishing articles), HTML/CSS, Playwright, Jira, daily use of AI models (Claude, ChatGPT, Gemini).
Education: B.A. Geography – Surveying & GIS, Damanhur University, 2026, grade Very Good, ranked 3rd. GIS tools: ArcGIS Pro, QGIS, AutoCAD, Civil 3D.
Certificates: Claude 101 (Anthropic, 2026), AutoCAD.
Available: remote, full-time or part-time, can start immediately.
CV versions available: qa, data_entry, wordpress, ai_trainer.`,
};

// ---- متلمسش اللي تحت ده ----
let mode = 'collect';
try { if ($('⏰ الملخص اليومي').isExecuted) mode = 'digest'; } catch (e) {}
try { if ($('⏰ التقديم بالإيميل').isExecuted) mode = 'apply'; } catch (e) {}
return [{ json: { ...CONFIG, mode, runAt: new Date().toISOString() } }];

// 🔗 بيجهّز لينكات كل المصادر (كل لينك = طلب واحد)
const c = $('⚙️ الإعدادات').first().json;
const out = [];
const add = (source, kind, url) => out.push({ json: { source, kind, url } });
const enc = encodeURIComponent;

// LinkedIn (صفحات الزوار العامة، من غير تسجيل دخول) — ريموت، آخر 24 ساعة
for (const loc of c.linkedinLocations) {
  for (const kw of c.linkedinKeywords) {
    add('LinkedIn', 'linkedin',
      `https://www.linkedin.com/jobs-guest/jobs/api/seeMoreJobPostings/search?keywords=${enc(kw)}&location=${enc(loc)}&f_WT=2&f_TPR=r86400&start=0`);
  }
}

// مستقل: آخر المشاريع + بحث بكلمات
add('مستقل', 'mostaql_rss', 'https://mostaql.com/rss');
for (const kw of c.mostaqlKeywords) {
  add('مستقل', 'mostaql_html', `https://mostaql.com/projects?keyword=${enc(kw)}&sort=latest`);
}

// Bayt (مصر والسعودية والإمارات — ريموت)
for (const u of c.baytPages) add('Bayt', 'bayt', u);

// مواقع الريموت العالمية (APIs مجانية). Remotive بيطلب 4 مرات في اليوم بالكتير
const hour = $now.hour;
for (const q of c.remoteApiSearches) {
  add('Himalayas', 'himalayas', `https://himalayas.app/jobs/api/search?q=${enc(q)}&worldwide=true&sort=recent`);
}
if (hour % 6 < 3) add('Remotive', 'remotive', 'https://remotive.com/api/remote-jobs?limit=150');
add('Jobicy', 'jobicy', 'https://jobicy.com/api/v2/remote-jobs?count=100&geo=emea');

return out;

// 🧹 بيفك الصفحات اللي اتجابت، ويوحّد شكل الوظايف، ويشيل اللي مش مناسب
const c = $('⚙️ الإعدادات').first().json;
const reqs = $('🔗 المصادر').all();
const responses = $input.all();

const ent = (s) => String(s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(+d))
  .replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const strip = (s) => ent(String(s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, (_, x) => ent(x)).replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|li|div|h\d)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')).replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const pick = (s, re) => { const m = String(s || '').match(re); return m ? m[1] : ''; };
const parseJSON = (t) => { try { return typeof t === 'string' ? JSON.parse(t) : t; } catch (e) { return null; } };

const jobs = [];
const errors = [];
const push = (j) => jobs.push({
  source: j.source, title: strip(j.title).slice(0, 200), company: strip(j.company).slice(0, 120),
  location: strip(j.location).slice(0, 120), url: String(j.url || '').trim(),
  posted: j.posted ? String(j.posted) : '', description: strip(j.description).slice(0, 4000),
});

function parseLinkedIn(html, source) {
  for (const block of String(html).split(/<li[\s>]/).slice(1)) {
    const id = pick(block, /urn:li:jobPosting:(\d+)/);
    if (!id) continue;
    push({ source, url: `https://www.linkedin.com/jobs/view/${id}/`,
      title: pick(block, /base-search-card__title[^>]*>([\s\S]*?)<\/h3>/),
      company: pick(block, /base-search-card__subtitle[^>]*>([\s\S]*?)<\/h4>/),
      location: pick(block, /job-search-card__location[^>]*>([\s\S]*?)<\/span>/),
      posted: pick(block, /<time[^>]*datetime="([^"]+)"/), description: '' });
  }
}
function parseMostaqlRss(xml, source) {
  for (const it of String(xml).split(/<item>/).slice(1)) {
    push({ source, title: pick(it, /<title>([\s\S]*?)<\/title>/), url: ent(pick(it, /<link>([\s\S]*?)<\/link>/)),
      description: pick(it, /<description>([\s\S]*?)<\/description>/), posted: pick(it, /<pubDate>([\s\S]*?)<\/pubDate>/),
      company: 'مشروع فري لانس', location: 'عن بعد' });
  }
}
function parseMostaqlHtml(html, source) {
  for (const row of String(html).split(/class="project-row/).slice(1)) {
    const m = row.match(/<a href="(https:\/\/mostaql\.com\/project\/[^"]+)"[^>]*>([\s\S]*?)<\/a>/);
    if (!m) continue;
    push({ source, url: m[1], title: m[2], posted: pick(row, /datetime="([^"]+)"/),
      description: pick(row, /class="[^"]*project__brief[^"]*"[^>]*>([\s\S]*?)<\/(?:p|div)>/),
      company: 'مشروع فري لانس', location: 'عن بعد' });
  }
}
function parseBayt(html, source) {
  for (const b of String(html).split(/data-js-job/).slice(1)) {
    const m = b.match(/<h2[^>]*>\s*<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/);
    if (!m) continue;
    const wrap = pick(b, /job-company-location-wrapper[^>]*>([\s\S]*?)<\/div>\s*<\/div>/) || b;
    const links = [...wrap.matchAll(/<a[^>]*>([\s\S]*?)<\/a>/g)].map((x) => strip(x[1])).filter(Boolean);
    push({ source, url: m[1].startsWith('http') ? m[1] : 'https://www.bayt.com' + m[1], title: m[2],
      company: links[0] || '', location: links.slice(1).join(', ') || 'Remote',
      description: pick(b, /class="jb-descr[^"]*"[^>]*>([\s\S]*?)<\/div>/) });
  }
}
const okLoc = (l) => !l || /worldwide|anywhere|emea|egypt|mena|middle east|africa|global|arab|saudi|uae|gulf/i.test(l);
function parseRemotive(t, source) {
  for (const j of (parseJSON(t) || {}).jobs || []) {
    if (!okLoc(j.candidate_required_location)) continue;
    push({ source, url: j.url, title: j.title, company: j.company_name, location: j.candidate_required_location,
      posted: j.publication_date, description: j.description });
  }
}
function parseHimalayas(t, source) {
  for (const j of (parseJSON(t) || {}).jobs || []) {
    const loc = (j.locationRestrictions || []).map((x) => (typeof x === 'string' ? x : x.name || x.alpha2 || '')).join(', ');
    if (!okLoc(loc)) continue;
    push({ source, url: (String(j.guid || '').startsWith('http') ? j.guid : j.applicationLink), title: j.title,
      company: j.companyName, location: loc || 'Worldwide',
      posted: j.pubDate ? new Date(+j.pubDate * (j.pubDate < 1e12 ? 1000 : 1)).toISOString() : '',
      description: j.description || j.excerpt });
  }
}
function parseJobicy(t, source) {
  for (const j of (parseJSON(t) || {}).jobs || []) {
    const loc = Array.isArray(j.jobGeo) ? j.jobGeo.join(', ') : j.jobGeo;
    if (!okLoc(loc)) continue;
    push({ source, url: j.url, title: j.jobTitle, company: j.companyName, location: loc,
      posted: j.pubDate, description: j.jobDescription || j.jobExcerpt });
  }
}
const P = { linkedin: parseLinkedIn, mostaql_rss: parseMostaqlRss, mostaql_html: parseMostaqlHtml, bayt: parseBayt,
  remotive: parseRemotive, himalayas: parseHimalayas, jobicy: parseJobicy };

responses.forEach((r, i) => {
  const req = (reqs[i] || {}).json || {};
  const body = r.json.data !== undefined ? r.json.data : r.json;
  if (r.json.error || body === undefined) { errors.push(req.source + ': ' + JSON.stringify(r.json.error || 'empty').slice(0, 120)); return; }
  try { P[req.kind](body, req.source); } catch (e) { errors.push(req.source + ': ' + e.message); }
});

// فلترة + شيل المكرر جوه نفس المرة
const inc = new RegExp(c.includeRegex, 'i');
const exc = new RegExp(c.excludeRegex, 'i');
const seen = new Set();
const out = [];
for (const j of jobs) {
  if (!j.title || !/^https?:\/\//.test(j.url)) continue;
  j.url = j.url.replace(/[?#].*$/, '');
  const key = j.url.toLowerCase();
  const key2 = (j.title + '|' + j.company).toLowerCase();
  if (seen.has(key) || seen.has(key2)) continue;
  seen.add(key); seen.add(key2);
  if (exc.test(j.title)) continue;
  const hay = j.title + ' ' + j.description.slice(0, 1500);
  // لازم كلمة من includeRegex تكون في العنوان أو الوصف
  // (LinkedIn مستثناة لأن وصفها بيتجاب بعدين، والبحث نفسه بالكلمة)
  if (j.source !== 'LinkedIn' && !inc.test(hay)) continue;
  const emails = (j.description.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [])
    .filter((e) => !/example|noreply|no-reply|sentry|wixpress/i.test(e));
  const rel = (j.title.match(new RegExp(c.includeRegex, 'gi')) || []).length * 3
    + (hay.match(new RegExp(c.includeRegex, 'gi')) || []).length
    + (/arab|عرب|egypt|مصر/i.test(hay) ? 4 : 0);
  out.push({ ...j, apply_email: emails[0] || '', rel, job_key: key });
}

// لو مفيش ولا وظيفة، الفرع بيقف هنا (والأخطاء بتبان في الـ Executions)
if (errors.length) console.log('مصادر فشلت:', errors.slice(0, 15));
return out.map((j) => ({ json: j }));

// ✂️ بياخد أحسن الوظايف الجديدة (بعد شيل اللي اتشاف قبل كده) عشان ما نصرفش على الـ AI
//    وبيجهّز لينك تفاصيل وظايف LinkedIn (عشان الوصف الكامل)
const c = $('⚙️ الإعدادات').first().json;
const items = $input.all().map((i) => i.json).filter((j) => j.title);
items.sort((a, b) => b.rel - a.rel);
return items.slice(0, c.maxAiJobsPerRun).map((j) => {
  const id = j.source === 'LinkedIn' ? (j.url.match(/\/view\/(\d+)/) || [])[1] : '';
  return { json: { ...j, detail_url: id ? `https://www.linkedin.com/jobs-guest/jobs/api/jobPosting/${id}` : '' } };
});

// 🧩 بيحط الوصف الكامل لوظايف LinkedIn (لو اتجاب)
const reqs = $('✂️ أحسن الوظايف').all();
const strip = (s) => String(s || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|li|div|h\d)>/gi, '\n').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
return $input.all().map((res, i) => {
  const j = { ...(reqs[i] || {}).json };
  const html = typeof res.json.data === 'string' ? res.json.data : '';
  if (j.detail_url && html) {
    const m = html.match(/show-more-less-html__markup[^>]*>([\s\S]*?)<\/div>/);
    if (m) j.description = strip(m[1]).slice(0, 4000);
    const crit = [...html.matchAll(/description__job-criteria-text[^>]*>([\s\S]*?)<\/span>/g)].map((x) => strip(x[1])).join(' / ');
    if (crit) j.description = (j.description + '\nCriteria: ' + crit).trim();
    const em = (j.description.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/) || [])[0];
    if (em && !j.apply_email) j.apply_email = em;
  }
  delete j.detail_url;
  return { json: j };
});

// 🤖 بيجهّز طلب تقييم لكل وظيفة
// ---- مكتبة صغيرة: بتبني طلب للذكاء الاصطناعي (Gemini / ChatGPT / Claude) ----
function aiRole(c, role) {
  let { provider, model } = c[role];
  if (!c.keys[provider]) { provider = c.scorer.provider; model = c.scorer.model; }
  if (!c.keys[provider]) throw new Error('حط مفتاح ' + provider + ' في ⚙️ الإعدادات');
  return { provider, model, key: c.keys[provider] };
}
function aiRequest(r, system, user, maxTokens) {
  if (r.provider === 'gemini') {
    const gen = { responseMimeType: 'application/json', temperature: 0.2, maxOutputTokens: maxTokens };
    if (/^gemini-2\.5-flash/.test(r.model)) gen.thinkingConfig = { thinkingBudget: 0 };
    return { ai_provider: r.provider,
      ai_url: `https://generativelanguage.googleapis.com/v1beta/models/${r.model}:generateContent`,
      ai_headers: { 'x-goog-api-key': r.key, 'content-type': 'application/json' },
      ai_body: { systemInstruction: { parts: [{ text: system }] }, contents: [{ role: 'user', parts: [{ text: user }] }], generationConfig: gen } };
  }
  if (r.provider === 'openai') {
    return { ai_provider: r.provider, ai_url: 'https://api.openai.com/v1/chat/completions',
      ai_headers: { Authorization: 'Bearer ' + r.key, 'content-type': 'application/json' },
      ai_body: { model: r.model, response_format: { type: 'json_object' }, max_completion_tokens: maxTokens * 3,
        messages: [{ role: 'system', content: system }, { role: 'user', content: user }] } };
  }
  if (r.provider === 'claude') {
    return { ai_provider: r.provider, ai_url: 'https://api.anthropic.com/v1/messages',
      ai_headers: { 'x-api-key': r.key, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      ai_body: { model: r.model, max_tokens: maxTokens, system,
        messages: [{ role: 'user', content: user + '\n\nReply with the JSON object only.' }] } };
  }
  throw new Error('provider لازم يكون gemini أو openai أو claude');
}
function aiText(provider, res) {
  if (!res || res.error) return '';
  if (provider === 'gemini') return (((res.candidates || [])[0] || {}).content || { parts: [] }).parts.map((p) => p.text || '').join('');
  if (provider === 'openai') return (((res.choices || [])[0] || {}).message || {}).content || '';
  if (provider === 'claude') return (res.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  return '';
}
function aiJSON(text) {
  const m = String(text || '').match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch (e) { return null; }
}
const c = $('⚙️ الإعدادات').first().json;
const r = aiRole(c, 'scorer');
const system = 'You screen job posts for ONE candidate and answer ONLY with a JSON object. Be strict and realistic, never optimistic.';
return $input.all().map((it) => {
  const j = it.json;
  const user = `CANDIDATE PROFILE:
${c.profile}

JOB POST (source: ${j.source}):
Title: ${j.title}
Company: ${j.company}
Location: ${j.location}
URL: ${j.url}
Description:
${(j.description || '(no description, judge from title/company/location)').slice(0, 3500)}

Return this JSON:
{"score": 0-100 (realistic chance this candidate gets an interview/acceptance),
 "cv": one of "qa" | "data_entry" | "wordpress" | "ai_trainer" (best CV version to send),
 "why_ar": "سبب مختصر بالعامية المصرية ليه مناسبة أو لأ (25 كلمة بالكتير)",
 "missing_ar": "أهم حاجة ناقصاه للوظيفة دي بالعامية المصرية (15 كلمة بالكتير) أو فاضي",
 "red_flags_ar": "علامات نصب أو شروط مستحيلة بالعامية المصرية أو فاضي",
 "apply_email": "the email address the post asks applicants to send CVs to, or empty string"}

Scoring rules:
- Restricted to residents of countries other than Egypt (e.g. US only, UK only, Saudi residents only), on-site, or hybrid: score 15 or less.
- Needs fluent/C1/native English or lots of English calls: score 30 or less.
- Needs clearly more experience than he has (he has ~1 year QA, ~2 years data entry): score 40 or less.
- Arabic-language AI work (AI training, rating, annotation, localization, Arabic review) at entry or junior level, open to Egypt: score high.
- Freelance projects (source مستقل): score by whether he can deliver this exact project with his stated skills.
